<body>
    <div class="npc-status-wrapper"></div>

    <script>
        (function() {
            var scripts = document.getElementsByTagName('script');
            var currentScript = scripts[scripts.length - 1];
            var wrapper = currentScript.previousElementSibling;

            var npcs = [];
            var currentIndex = 0;

            /* ========== 性爱元素配置 ========== */
            var sexElements = [
                "抚摸", "口交", "乳交", "普通性爱", "跳蛋", "假屌", "乳夹",
                "肛交", "sm", "捆绑", "群交", "排泄调教", "露出调教",
                "称呼控制", "命令自辱", "宠物化", "纹身", "乳环", "阴环",
                "内射", "颜射"
            ];

            function getMessageData() {
                var chatMessages = getChatMessages(getCurrentMessageId());
                if (!chatMessages || chatMessages.length === 0) return null;
                return chatMessages[0].message;
            }

            function parseData(messageText) {
                var tagMatch = messageText.match(/<npc_status>([\s\S]*?)<\/npc_status>/);
                if (!tagMatch || !tagMatch[1]) return;

                var currentNpc = null;
                var lines = tagMatch[1].trim().split('\n');

                lines.forEach(function(line) {
                    var match = line.match(/\[(.*?)\]\s*(.*)/);
                    if (match) {
                        var key = match[1].trim();
                        var val = match[2].trim();

                        if (key === '姓名') {
                            if (currentNpc) npcs.push(currentNpc);
                            currentNpc = {
                                name: val,
                                value: '未知',
                                targetName: '辰',
                                attitude: '未知',
                                stats: { '口交': '0', '揉乳': '0', '性交': '0', '肛交': '0' },
                                threat: { name: '无', title: '', desc: '' },
                                network: {
                                    backers: [],
                                    accomplices: [],
                                    family: []
                                }
                            };
                        } else if (currentNpc) {
                            if (key === '身价') {
                                currentNpc.value = val;
                            } else if (key === '当前威胁') {
                                if (val !== '未知' && val !== '无') {
                                    var parts = val.split('|');
                                    currentNpc.threat = {
                                        name: parts[0] ? parts[0].trim() : '未知',
                                        title: parts[1] ? parts[1].trim() : '',
                                        desc: parts[2] ? parts[2].trim() : ''
                                    };
                                }
                            } else if (key === '后台') {
                                if (val !== '未知' && val !== '无') {
                                    var parts = val.split('|');
                                    currentNpc.network.backers.push({
                                        name: parts[0] ? parts[0].trim() : '未知',
                                        title: parts[1] ? parts[1].trim() : '',
                                        desc: parts[2] ? parts[2].trim() : ''
                                    });
                                }
                            } else if (key === '帮凶') {
                                if (val !== '未知' && val !== '无') {
                                    var parts = val.split('|');
                                    currentNpc.network.accomplices.push({
                                        name: parts[0] ? parts[0].trim() : '未知',
                                        title: parts[1] ? parts[1].trim() : '',
                                        desc: parts[2] ? parts[2].trim() : ''
                                    });
                                }
                            } else if (key === '女眷') {
                                if (val !== '未知' && val !== '无') {
                                    var parts = val.split('|');
                                    currentNpc.network.family.push({
                                        name: parts[0] ? parts[0].trim() : '未知',
                                        title: parts[1] ? parts[1].trim() : '',
                                        desc: parts[2] ? parts[2].trim() : ''
                                    });
                                }
                            } else if (currentNpc.stats.hasOwnProperty(key)) {
                                currentNpc.stats[key] = val;
                            } else {
                                var attitudeMatch = key.match(/^对(.+?)的态度$/);
                                if (attitudeMatch) {
                                    currentNpc.targetName = attitudeMatch[1];
                                    currentNpc.attitude = val;
                                }
                            }
                        }
                    }
                });

                if (currentNpc) npcs.push(currentNpc);
            }

            function getValueLevelClass(val) {
                if (val.indexOf('极低') !== -1) return 'val-level-1';
                if (val.indexOf('极高') !== -1) return 'val-level-5';
                if (val.indexOf('低') !== -1) return 'val-level-2';
                if (val.indexOf('中') !== -1) return 'val-level-3';
                if (val.indexOf('高') !== -1) return 'val-level-4';
                return 'val-level-1';
            }

            function renderNetworkItems(label, items) {
                if (!items || items.length === 0) return '';
                var html = '<div class="network-item"><div class="network-label">[' + label + ']</div>';
                items.forEach(function(item) {
                    html += '<div class="network-info"><span class="network-name">' + item.name + '</span>';
                    if (item.title) html += ' | ' + item.title;
                    if (item.desc) html += ' | ' + item.desc;
                    html += '</div>';
                });
                html += '</div>';
                return html;
            }

            /* ========== 填入输入框逻辑 ========== */
            function insertIntoChatbox(text) {
                try {
                    /* 通过 parent.document 访问酒馆主界面的输入框 */
                    var ta = parent.document.getElementById('send_textarea');
                    if (ta) {
                        var c = ta.value.trim();
                        if (c) {
                            ta.value = c + '\n' + text;
                        } else {
                            ta.value = text;
                        }
                        /* 触发输入事件，让酒馆底层感知到内容变化并调整高度 */
                        ta.dispatchEvent(new Event('input', { bubbles: true }));
                        /* 自动获取焦点，方便哥哥直接回车发送或继续修改 */
                        ta.focus();
                    } else {
                        console.error("未找到 id 为 send_textarea 的元素");
                    }
                } catch (e) {
                    console.error("填入聊天框时发生错误:", e);
                }
            }

            function render() {
                if (npcs.length === 0) {
                    wrapper.innerHTML = '<div class="npc-card"><div class="npc-loading">❌ 未找到猎物数据</div></div>';
                    return;
                }

                var data = npcs[currentIndex];
                var total = npcs.length;
                var valueClass = getValueLevelClass(data.value);

                var threatHtml = '';
                if (data.threat.name !== '无' && data.threat.name !== '未知') {
                    threatHtml = '<div class="network-item"><div class="network-label">[当前威胁]</div>' +
                                 '<div class="network-info"><span class="network-name">' + data.threat.name + '</span>' +
                                 (data.threat.title ? ' | ' + data.threat.title : '') +
                                 (data.threat.desc ? ' | ' + data.threat.desc : '') +
                                 '</div></div>';
                } else {
                    threatHtml = '<div class="network-item"><div class="network-label">[当前威胁]</div><div class="network-info">暂无威胁</div></div>';
                }

                /* 生成多选框HTML */
                var checkboxesHtml = sexElements.map(function(item, index) {
                    return `<label class="action-label">
                                <input type="checkbox" name="sex_element" value="${item}">
                                <span>${item}</span>
                            </label>`;
                }).join('');

                var html = `
                    <div class="npc-card">
                        <div class="npc-header">
                            <div class="name-page-group">
                                <div class="name-group">
                                    <span class="npc-name">${data.name}</span>
                                </div>
                                <button class="quick-action-btn" title="对${data.name}执行操作">
                                    ⚡ 快捷操作
                                </button>
                                ${total > 1 ? `
                                <div class="npc-pagination">
                                    <button class="page-btn prev-btn" ${currentIndex === 0 ? 'disabled' : ''}>◀</button>
                                    <span class="page-info">${currentIndex + 1}/${total}</span>
                                    <button class="page-btn next-btn" ${currentIndex === total - 1 ? 'disabled' : ''}>▶</button>
                                </div>
                                ` : ''}
                            </div>
                            <div class="value-group">
                                <span class="value-label">身价</span>
                                <span class="npc-value ${valueClass}">${data.value}</span>
                            </div>
                        </div>

                        <div class="npc-row">
                            <span class="npc-label">对${data.targetName}的态度</span>
                            <span class="npc-text">${data.attitude}</span>
                        </div>

                        <div class="npc-stats">
                            <div class="stat-box">
                                <span class="stat-label">口交</span>
                                <span class="stat-num">${data.stats['口交']}</span>
                            </div>
                            <div class="stat-box">
                                <span class="stat-label">揉乳</span>
                                <span class="stat-num">${data.stats['揉乳']}</span>
                            </div>
                            <div class="stat-box">
                                <span class="stat-label">性交</span>
                                <span class="stat-num">${data.stats['性交']}</span>
                            </div>
                            <div class="stat-box">
                                <span class="stat-label">肛交</span>
                                <span class="stat-num">${data.stats['肛交']}</span>
                            </div>
                        </div>

                        <details class="npc-threat-details">
                            <summary>威胁与关系网</summary>
                            <div class="network-content">
                                ${threatHtml}
                                ${renderNetworkItems('后台', data.network.backers)}
                                ${renderNetworkItems('帮凶', data.network.accomplices)}
                                ${renderNetworkItems('女眷', data.network.family)}
                            </div>
                        </details>

                        <!-- 隐藏的操作面板 -->
                        <div class="action-panel-overlay">
                            <div class="action-panel-header">对 ${data.name} 的操作指令</div>
                            <div class="panel-scroll-area">
                                <div class="action-section">
                                    <div class="action-section-title">【基础操作】(单选)</div>
                                    <div class="radio-group">
                                        <label class="action-label">
                                            <input type="radio" name="base_action" value="救下她" checked>
                                            <span>救下她</span>
                                        </label>
                                        <label class="action-label">
                                            <input type="radio" name="base_action" value="看她继续">
                                            <span>看她继续</span>
                                        </label>
                                        <label class="action-label">
                                            <input type="radio" name="base_action" value="亲自上她">
                                            <span>亲自上她</span>
                                        </label>
                                    </div>
                                </div>
                                <div class="action-section">
                                    <div class="action-section-title">【性爱元素】(多选)</div>
                                    <div class="checkbox-group">
                                        ${checkboxesHtml}
                                    </div>
                                </div>
                            </div>
                            <div class="action-panel-footer">
                                <button class="action-btn cancel-btn">取消</button>
                                <button class="action-btn confirm-btn">确认填入</button>
                            </div>
                        </div>
                    </div>
                `;

                wrapper.innerHTML = html;

                /* ====== 绑定事件 ====== */
                var card = wrapper.querySelector('.npc-card');
                var quickBtn = card.querySelector('.quick-action-btn');
                var panel = card.querySelector('.action-panel-overlay');
                var cancelBtn = card.querySelector('.cancel-btn');
                var confirmBtn = card.querySelector('.confirm-btn');

                if (quickBtn && panel) {
                    quickBtn.addEventListener('click', function() {
                        panel.style.display = 'flex';
                    });
                }

                if (cancelBtn && panel) {
                    cancelBtn.addEventListener('click', function() {
                        panel.style.display = 'none';
                        /* 重置选项 */
                        var radios = panel.querySelectorAll('input[type="radio"]');
                        if(radios.length > 0) radios[0].checked = true;
                        var checkboxes = panel.querySelectorAll('input[type="checkbox"]');
                        checkboxes.forEach(function(cb) { cb.checked = false; });
                    });
                }

                if (confirmBtn && panel) {
                    confirmBtn.addEventListener('click', function() {
                        var baseAction = panel.querySelector('input[name="base_action"]:checked');
                        var selectedElements = panel.querySelectorAll('input[name="sex_element"]:checked');

                        var actionText = baseAction ? baseAction.value : '';
                        var elementsText = Array.from(selectedElements).map(function(el) { return el.value; }).join('，');

                        /* 组合最终字符串 */
                        var finalString = actionText;
                        if (elementsText) {
                            finalString += "，性爱元素：" + elementsText;
                        }
                        finalString += "|";

                        /* 填入主界面输入框 */
                        insertIntoChatbox(finalString);

                        /* 关闭面板并重置 */
                        panel.style.display = 'none';
                        var radios = panel.querySelectorAll('input[type="radio"]');
                        if(radios.length > 0) radios[0].checked = true;
